import React from "react";
import {
  BrowserRouter as Router,
  Route,
  Routes,
  Navigate,
  useParams,
} from "react-router-dom";
import Home from "./pages/Home";
import Signup from "./pages/Signup";
import Login from "./pages/Login";
import Upload from "./pages/Upload";
import Dashboard from "./components/Dashboard";
import { WishlistProvider } from "./context/WishlistContext";
import Navbar from "./components/Navbar";
import Homes from "./pages/Homes";
import { AuthProvider, AuthContext } from "./context/AuthContext";
import { useContext } from "react";

const DashboardWrapper = () => {
  const { userId } = useParams();
  const { userId: loggedInUser } = useContext(AuthContext);
  console.log("DashboardWrapper:", { userId, loggedInUser });
  if (!loggedInUser) {
    console.log("Redirecting to login: No loggedInUser");
    return <Navigate to="/login" />;
  }
  const finalUserId = userId || loggedInUser;
  console.log("Using finalUserId:", finalUserId);
  return <Dashboard userId={finalUserId} />;
};

function App() {
  return (
    <AuthProvider>
      <WishlistProvider>
        <Router>
          <Navbar />
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/login" element={<Login />} />
            <Route
              path="/upload"
              element={
                <RequireAuth>
                  <Upload />
                </RequireAuth>
              }
            />
            <Route path="/dashboard/:userId" element={<DashboardWrapper />} />
            <Route path="/homes" element={<Homes />} />
            <Route
              path="*"
              element={
                <div
                  style={{
                    textAlign: "center",
                    padding: "20px",
                    minHeight: "100vh",
                    backgroundColor: "#f0f0f0",
                  }}
                >
                  <h2>404 - Page Not Found</h2>
                  <p>The page you are looking for does not exist.</p>
                </div>
              }
            />
          </Routes>
        </Router>
      </WishlistProvider>
    </AuthProvider>
  );
}

const RequireAuth = ({ children }) => {
  const { userId } = useContext(AuthContext);
  return userId ? children : <Navigate to="/login" />;
};

export default App;
